css:
@custom-variant dark (&:where(.dark, .dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-info: var(--info);
  --color-info-foreground: var(--info-foreground);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
}

:root {
  --radius: .375rem;
  --background: #f8f9fb;
  --foreground: #20242c;
  --card: #ffffff;
  --card-foreground: #20242c;
  --popover: #ffffff;
  --popover-foreground: #20242c;
  --primary: #25272c;
  --primary-foreground: #ffffff;
  --secondary: #e8ecf4;
  --secondary-foreground: #20242c;
  --muted: #f4f4f5;
  --muted-foreground: #5e6674;
  --accent: #eff0ff;
  --accent-foreground: #5961cf;
  --border: #dedee3;
  --input: #7d8797;
  --ring: #6673e8;
  --destructive: #b02a3b;
  --destructive-foreground: #ffffff;
  --success: #22673f;
  --success-foreground: #ffffff;
  --warning: #875300;
  --warning-foreground: #ffffff;
  --info: #2457b2;
  --info-foreground: #ffffff;
}

.dark {
  --background: #101011;
  --foreground: #eeeeef;
  --card: #171718;
  --card-foreground: #eeeeef;
  --popover: #1c1c1f;
  --popover-foreground: #eeeeef;
  --primary: #e7e7ea;
  --primary-foreground: #18181a;
  --secondary: #303034;
  --secondary-foreground: #eeeeef;
  --muted: #29292d;
  --muted-foreground: #aaaab3;
  --accent: #25252e;
  --accent-foreground: #a8aeff;
  --border: #3d3d43;
  --input: #6c6c75;
  --ring: #9699d6;
  --destructive: #ff9da8;
  --destructive-foreground: #271217;
  --success: #92ddb0;
  --success-foreground: #12251a;
  --warning: #f4c876;
  --warning-foreground: #281d0c;
  --info: #a4c4ff;
  --info-foreground: #13213b;
}

/* baseui-cn foundation */
@layer base {
  :root { color-scheme: light; }
  .dark { color-scheme: dark; }
}
@keyframes loading-spin { to { transform: rotate(360deg); } }
@utility loading-spinner { animation: loading-spin 1s linear infinite; }
@media (prefers-reduced-motion: reduce) {
  .loading-spinner { animation: none; }
}
